def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    Z = np.ones((n, 1))
    if len(labs) > 1:
        Z = np.column_stack([Z] + [(np.array(feats.stratum) == s).astype(float) for s in labs[1:]])

    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))

    def pv(l1, l0): return stats.chi2.sf(max(2 * (l1 - l0), 0.0), 1)
    R = np.corrcoef(X, rowvar=False)
    sel = []
    base = ll(Z)
    while len(sel) < MAX_DRIVERS:
        alpha = (0.5 if not sel else 0.05) / p
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l1 = ll(np.column_stack([Z, X[:, sel + [j]]]))
            if best is None or l1 > best[1]: best = (j, l1)
        if best is None or pv(best[1], base) >= alpha: break
        sel.append(best[0]); base = best[1]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        full = ll(np.column_stack([Z, X[:, sel]]))
        ps = [pv(full, ll(np.column_stack([Z, X[:, [k for k in sel if k != j]]]))) for j in sel]
        worst = int(np.argmax(ps))
        if ps[worst] >= 0.05 / p: sel.pop(worst); changed = True
    prods = []
    npairs = p * (p + 1) / 2
    M0 = np.column_stack([Z, X[:, sel]]) if sel else Z
    cands = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            Mm = np.column_stack([Z, X[:, mains]])
            l0 = ll(Mm); l1 = ll(np.column_stack([Mm, X[:, a] * X[:, b]]))
            q = pv(l1, l0)
            if q < 0.002 / npairs: cands.append((q, a, b))
    cands.sort()
    for q, a, b in cands[:2]:
        prods.append((ids[a], ids[b]))
        for k in (a, b):
            if k not in sel: sel.append(k)
    drivers = tuple(ids[k] for k in sel[:MAX_DRIVERS])
    return Design(drivers=drivers, columns=tuple(ids[k] for k in sel), products=tuple(prods), loadings={})

